INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422600, 16503, 'The Guardian', 'en', 'Jamie Carragher hit with HMRC bankruptcy petition over unpaid tax bill', 'https://www.theguardian.com/football/2026/aug/27/jamie-carragher-hit-with-hmrc-bankruptcy-petition-over-unpaid-tax-bill', 'High court proceedings issued against former player ‘Matter resolved imminently,’ says representative Jamie Carragher could face bankruptcy after HM Revenue and Customs (HMRC) issued a bankruptcy petition against him. Court records show HMRC issued the petition against the former Liverpool defender on Wednesday afternoon over an unpaid tax bill. No further details of the case are available. An HMRC spokesperson said: “We take a supportive approach to dealing with customers who have tax debts and do everything we can to help those who engage with us to get out of debt, such as offering instalme', 'https://i.guim.co.uk/img/media/20eed1b380551a42dc3ed32aba4ea63bfe2b58f9/307_0_3072_2457/master/3072.jpg?width=140&quality=85&auto=format&fit=max&s=ae24d3de3de12c98ae0471713154b912', '2026-08-27T14:23:17+00:00', '2026-08-28T12:49:07.449958'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
