INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422599, 16507, 'The Guardian', 'en', 'Callaway cuts ties with Good Good Golf over ad depicting violence against woman', 'https://www.theguardian.com/sport/2026/aug/27/good-good-golf-garrett-clark-apology-callaway-ad-backlash', 'Golf giant ends partnership with YouTube group Retailers have pulled Good Good products from shelves Garrett Clark says controversial skit was in ‘poor taste’ Callaway has ended its relationship with Good Good Golf amid mounting fallout from an advert that many believe made light of violence against women. The golf equipment manufacturer announced the decision on Thursday, cutting ties with one of the world’s most popular YouTube sports channels effective immediately. Callaway also said it would donate $1m to organizations working to prevent violence against women and support survivors of dome', 'https://i.guim.co.uk/img/media/4cb669f6afa66e13fd9ac3217229dc05ff858d00/515_0_5145_4116/master/5145.jpg?width=140&quality=85&auto=format&fit=max&s=b323ad7b88fdbcecfa3857c57b76f9d2', '2026-08-27T20:15:51+00:00', '2026-08-28T12:49:07.438904'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
