INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422554, 16519, 'BBC News', 'en', '''Our parents were crossing the border an hour before the flood hit''', 'https://www.bbc.co.uk/news/articles/cn5dzldq1pzo', 'Authorities say more than 1,300 people are missing, including dozens of Americans and Canadians, as families await word on loved ones thought to be caught in the Nepal flash floods.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/192a/live/9d95b090-a237-11f1-80a2-67c89a95284e.jpg', '2026-08-28T00:22:20+00:00', '2026-08-28T12:48:59.971596'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422572, 16519, 'The Guardian', 'en', '‘So desperately loved’: ADF member among dozens of Australians missing in Nepal floods as families pray for safe return', 'https://www.theguardian.com/world/2026/aug/28/family-missing-australians-nepal-tibet-flash-floods', 'Relatives ‘really worried, but hopeful’ as they wait anxiously for news in the aftermath of the flash flooding disaster Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast The families of an Australian defence force member and two Sydney boys who went missing with their parents in Nepal remain hopeful they will be found safe. Dozens of Australians are missing after devastating flooding on the Nepal-Tibet border. Nepal police on Friday said more than 1,500 people remained missing and 469 have been confirmed dead after massive flash', 'https://i.guim.co.uk/img/media/b13331200f050e02caee7ece44264ecb6200bdfc/0_0_5000_4000/master/5000.jpg?width=140&quality=85&auto=format&fit=max&s=3ef61799ec009188530e5023a34b401e', '2026-08-28T09:52:36+00:00', '2026-08-28T12:49:05.645397'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422575, 16519, 'The Guardian', 'en', '‘We praise God’: Australian woman feared missing in Nepal flooding makes contact with family', 'https://www.theguardian.com/australia-news/2026/aug/28/we-praise-god-australian-woman-feared-missing-in-nepal-flooding-makes-contact-with-family', 'Cara Severino has spoken with her parents – but still faces a trek of more than 110km to reach Kathmandu on foot ‘So desperately loved’: ADF member among dozens of Australians missing in Nepal floods as families pray for safe return How Nepali diaspora is responding to flood disaster and how Australians can help in relief effort Get our breaking news email , free app or daily news podcast An Australian woman has made contact with her family, more than two days after she was reported missing in flash flooding in Nepal. At least 469 people have been killed and more than 1,500 are missing after a', 'https://i.guim.co.uk/img/media/0d963d94c8e8e396ecb85228fcc92b2090f826ea/49_0_3750_3000/master/3750.jpg?width=140&quality=85&auto=format&fit=max&s=5b6ec2cabf1d6b60b987d78dd5e88fc4', '2026-08-28T08:15:23+00:00', '2026-08-28T12:49:05.689794'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422585, 16519, 'The Guardian', 'en', 'First Thing: Rescue efforts continue as death toll rises in Nepal-Tibet flood', 'https://www.theguardian.com/us-news/2026/aug/28/first-thing-rescue-efforts-continue-death-toll-rises-nepal-tibet-flood', 'More than 1,300 people are missing in Nepal and in Tibet after catastrophic flash floods swept through the region, killing at least 469. Plus: Six months of the war in Iran Don’t already get First Thing in your inbox? Sign up here Good morning. Rescue operations have resumed in Nepal and Tibet after a pause when a lake at the border began to overflow. The lake was formed when a wall of mud and debris hit the hub of Gyirong in Tibet on Wednesday, causing catastrophic flash floods that thundered down valleys and obliterated villages. What could have caused this deadly flash floods? Satellite ima', 'https://i.guim.co.uk/img/media/2ff39dfdb655e4d80a1d802fdb1bf6897aa17b57/688_0_6880_5504/master/6880.jpg?width=140&quality=85&auto=format&fit=max&s=36cc4fa5f2ae9d9607d28ec495f0f161', '2026-08-28T12:24:32+00:00', '2026-08-28T12:49:05.838269'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
