INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422700, 16519, 'Deutsche Welle', 'en', 'Nepal-China flood rescue on hold as lake breaks banks', 'https://news.google.?oc=5', 'Nepal-China flood rescue on hold as lake breaks banks DW.com', '', '2026-08-28T10:29:21+00:00', '2026-08-28T12:49:22.155774'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422711, 16519, 'France 24', 'en', 'Nepal flood survivors rescued from hydropower tunnel', 'https://www.france24.com/en/nepal-flood-survivors-rescued-from-hydropower-tunnel', 'Nepali soldiers rescued around 100 people trapped inside a flooded hydropower tunnel as the death toll from the Nepal-China floods continued to climb, with more than 1,500 people still missing. Rescue efforts were briefly suspended over fears that an overflowing landslide lake could trigger more flooding, while families across the disaster zone continue searching for loved ones.', 'https://s.france24.com/media/display/91d2d728-a2d8-11f1-a6cb-005056bf30b7/w:1024/p:16x9/EN-20260828-130127-130247-CS.jpg', '2026-08-28T12:38:01+00:00', '2026-08-28T12:49:23.694970'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422712, 16519, 'France 24', 'en', 'Nepal: A newly formed lake is sparking fears of more flooding along the Chinese border', 'https://www.france24.com/en/video/20260828-nepal-a-newly-formed-lake-is-sparking-fears-of-more-flooding-along-the-chinese-border', 'Rescue operations are continuing after the devastating Nepal-China floods, but authorities have ordered emergency teams to stay on high alert as a newly formed upstream lake threatens to burst and trigger fresh flooding. Satellite imagery suggests the lake formed in the same area where a glacier collapse on Wednesday unleashed the deadly chain of events. FRANCE 24''s Navodita Kumari has the latest from India.', 'https://s.france24.com/media/display/3ac3d868-a190-11f1-9918-005056bfb2b6/w:1024/p:16x9/2026-08-26T171120Z-701956187-RC2E6NA3ZW1B-RTRMADP-3-NEPAL-FLOODS.jpg', '2026-08-28T12:36:23+00:00', '2026-08-28T12:49:23.726608'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422714, 16519, 'France 24', 'en', '''Ran for our lives'': Tales of survival from Nepal-China disaster', 'https://www.france24.com/en/live-news/20260828-ran-for-our-lives-tales-of-survival-from-nepal-china-disaster', 'Some survivors of the deadly floods on the Nepal-China border ran for their lives, others narrowly missed disaster, but all were eyewitnesses to a major calamity and its aftermath.', 'https://s.france24.com/media/display/c4877f86-a2a4-11f1-8c93-005056bf30b7/w:1024/p:16x9/a445c491a2511f5d6e49b86a241ebbb831600f74.jpg', '2026-08-28T11:55:15+00:00', '2026-08-28T12:49:23.754422'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422715, 16519, 'France 24', 'en', 'Nepal and Tibet : around 93,000 people affected, according to the Red Cross', 'https://www.france24.com/en/nepal-and-tibet-around-93-000-people-affected-according-to-the-red-cross', 'The death toll continues to rise in the Nepal and Tibet floods as the situation remains fast-moving. The Red Cross says around 93,000 people have been affected. International aid is arriving from several countries, but rescue efforts have been hampered by the difficulty of coordinating operations in the remote Himalayan terrain. The epicentre of the disaster was only reached 48 hours after the floods began. FRANCE 24''s Jamie Smith-Maillet has the latest.', 'https://s.france24.com/media/display/c32e947a-a241-11f1-8ef7-005056a90284/w:1024/p:16x9/eeb7d109036331a0c0d020367f59af082ea071b3w.jpg', '2026-08-28T11:42:48+00:00', '2026-08-28T12:49:23.764898'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422717, 16519, 'France 24', 'en', 'Nepal: Army rescues hundreds trapped in tunnel as flood risk reignites', 'https://www.france24.com/en/video/20260828-nepal-army-rescues-hundreds-trapped-in-tunnel-as-flood-risk-reignites', '#Rescue operations are underway in #Nepal after devastating #floods killed hundreds and left more than 1,400 missing. The #RedCross has also raised concern over humanitarian #aid, as it estimates nearly 100,000 people were affected by the #disaster.', 'https://s.france24.com/media/display/9071bc6c-a2cb-11f1-8eff-005056bf30b7/w:1024/p:16x9/EN-NEpal-rescue-updates.png', '2026-08-28T10:36:51+00:00', '2026-08-28T12:49:23.787895'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422719, 16519, 'France 24', 'en', 'Nepal flash floods: ''Very challenging'' for survivors who have lost their homes and their families', 'https://www.france24.com/en/video/20260828-nepal-flash-floods-very-challenging-for-survivors-who-have-lost-their-homes-and-their-families', 'Alison Sargent is pleased to welcome Sunita Sharma, Head of Programs of Karuna-Shechen. While Nepal has considerable experience responding to natural disasters, the scale of the present devastation exposes a deeper challenge: Placing greater emphasis on preparedness. The immediate priorities are clear: finding those still missing and providing survivors with drinking water, food, shelter, clothing and medicine. But recovery cannot end there. Ultimately, they will need to rebuild confidence and entire communities. Given the scale of the destruction, that process could take years.', 'https://s.france24.com/media/display/528dfd0a-a2c3-11f1-81b1-005056bf30b7/w:1024/p:16x9/EN-20260828-091712-092608-CS.jpg', '2026-08-28T09:50:55+00:00', '2026-08-28T12:49:23.811752'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422721, 16519, 'France 24', 'en', 'Nepal flood disaster reconstructed minute by minute', 'https://www.france24.com/en/nepal-flood-disaster-reconstructed-minute-by-minute', 'New satellite imagery and video analysis show the deadly Nepal floods began when part of a glacier near the Chinese border collapsed, triggering a debris flow that raced downstream at up to 150 km/h and devastated communities over more than 80 kilometres. Scientists are still piecing together the exact sequence of events, while authorities warn the disaster may not be over as a newly formed lake upstream has started to overflow.', 'https://s.france24.com/media/display/f6cd2bda-a2bd-11f1-9da3-005056a97e36/w:1024/p:16x9/EN-20260828-090346-090618-CS.jpg', '2026-08-28T09:22:57+00:00', '2026-08-28T12:49:23.835034'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422723, 16519, 'France 24', 'en', 'In Tibet and Nepal, ''the most pressing fear is that the death toll could rise''', 'https://www.france24.com/en/in-tibet-and-nepal-the-most-pressing-fear-is-that-the-death-toll-could-rise', 'At least 472 people have been killed and more than 1,500 remain missing after devastating flash floods hit the Himalayan border between Nepal and China, where over 3,250 people have already been evacuated by helicopter. As rescuers race to find survivors, one of the biggest fears is that the death toll will continue to rise, with authorities also warning that an overflowing lake upstream could trigger more flooding. FRANCE 24''s Navodita Kumari has the latest.', 'https://s.france24.com/media/display/02f59162-a242-11f1-a302-005056bfb2b6/w:1024/p:16x9/2026-08-27T120902Z-886945342-RC207NAPVBUI-RTRMADP-3-NEPAL-FLOODS.jpg', '2026-08-28T09:16:45+00:00', '2026-08-28T12:49:23.860003'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422728, 16519, 'France 24', 'en', 'Countries step up aid for Nepal flood disaster', 'https://www.france24.com/en/countries-step-up-aid-for-nepal-flood-disaster', 'Countries including South Korea, India, China, the UK and the EU are ramping up rescue efforts and humanitarian aid after the devastating Nepal-China floods, with hundreds of foreign nationals still missing. Relief operations remain difficult in the Himalayan terrain, while authorities warn that a lake formed by the disaster could burst and trigger a second wave of flooding.', 'https://s.france24.com/media/display/6e40d538-a2bc-11f1-b7fd-005056a90284/w:1024/p:16x9/EN-20260828-100305-100443-CS.jpg', '2026-08-28T09:00:30+00:00', '2026-08-28T12:49:23.913512'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
